<script setup lang="ts">
import {ref,computed,watch,nextTick} from 'vue'
import {ChevronDown,ChevronRight,Check} from 'lucide-vue-next'
import {useHysRootAttrs} from '../../config'
import {useFloating} from '../../composables/useFloating'
export interface HysCascaderNode {label:string;value:string;children?:HysCascaderNode[];disabled?:boolean}
const props=withDefaults(defineProps<{modelValue:string[];options:HysCascaderNode[];disabled?:boolean;clearable?:boolean;filterable?:boolean;changeOnSelect?:boolean;showAllLevels?:boolean;separator?:string;placeholder?:string}>(),{showAllLevels:true,separator:' / ',placeholder:'选择分类'})
const emit=defineEmits<{'update:modelValue':[value:string[]];change:[value:string[]];clear:[]}>(),hysRootAttrs=useHysRootAttrs(),trigger=ref<HTMLElement>(),panel=ref<HTMLElement>(),query=ref(''),path=ref([...props.modelValue])
const {open,style,show,close}=useFloating(trigger,panel,{matchWidth:true})
watch(()=>props.modelValue,v=>path.value=[...v]);watch(open,v=>{if(v){path.value=[...props.modelValue];query.value=''}});watch(()=>props.disabled,v=>{if(v)close()})
const levels=computed(()=>{const result:HysCascaderNode[][]=[props.options];let nodes=props.options;for(const value of path.value){const match=nodes.find(n=>n.value===value);if(!match?.children?.length)break;nodes=match.children;result.push(nodes)}return result})
function update(value:string[]){emit('update:modelValue',value);emit('change',value)}
function select(node:HysCascaderNode,depth:number){if(node.disabled||props.disabled)return;path.value=[...path.value.slice(0,depth),node.value];if(props.changeOnSelect||!node.children?.length)update(path.value);if(!node.children?.length)close(true)}
const label=computed(()=>{let nodes=props.options;const parts=props.modelValue.map(value=>{const node=nodes.find(x=>x.value===value);nodes=node?.children||[];return node?.label||value});return props.showAllLevels?parts.join(props.separator):parts.at(-1)})
const matches=computed(()=>{const result:{label:string;path:string[]}[]=[];function walk(nodes:HysCascaderNode[],labels:string[]=[],values:string[]=[],disabled=false){for(const node of nodes){const blocked=disabled||node.disabled,nextLabels=[...labels,node.label],nextValues=[...values,node.value];if(!blocked&&(!node.children?.length||props.changeOnSelect)&&nextLabels.join(props.separator).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))result.push({label:nextLabels.join(props.separator),path:nextValues});if(node.children)walk(node.children,nextLabels,nextValues,blocked)}}walk(props.options);return result})
async function expand(){if(props.disabled)return;await show();await nextTick();(panel.value?.querySelector<HTMLElement>('input')||panel.value?.querySelector<HTMLElement>('.hys-ui-v4-level button:not(:disabled)'))?.focus()}
function keyboard(event:KeyboardEvent){if(event.isComposing||event.keyCode===229)return;if(event.key==='Escape'){event.preventDefault();close(true);return}const current=document.activeElement as HTMLElement;let level=current?.closest('.hys-ui-v4-level,.hys-ui-cascader-results');if(current?.tagName==='INPUT'){if(event.key!=='ArrowDown')return;event.preventDefault();panel.value?.querySelector<HTMLElement>('.hys-ui-cascader-results button,.hys-ui-v4-level button:not(:disabled)')?.focus();return}if(['ArrowUp','ArrowDown','Home','End'].includes(event.key)&&level){event.preventDefault();const buttons=Array.from(level.querySelectorAll<HTMLElement>('button:not(:disabled)')),index=buttons.indexOf(current),next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowUp'?-1:1)+buttons.length)%buttons.length;buttons[next]?.focus()}else if(level&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const levels=Array.from(panel.value?.querySelectorAll<HTMLElement>('.hys-ui-v4-level')||[]),index=levels.indexOf(level as HTMLElement);levels[index+(event.key==='ArrowRight'?1:-1)]?.querySelector<HTMLElement>('button:not(:disabled)')?.focus()}}
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-v4-relative"><button ref="trigger" class="hys-ui-v4-control hys-ui-pf-select-trigger" type="button" :disabled="disabled" :aria-expanded="open" aria-haspopup="dialog" @click="open?close():expand()" @keydown.down.prevent="expand"><span>{{label||placeholder}}</span><ChevronDown :size="16" class="hys-ui-pf-select-chevron"/></button><Teleport to="body"><div v-if="open" ref="panel" v-bind="hysRootAttrs" class="hys-ui-v4-menu hys-ui-pf-select-menu" :style="style" role="dialog" aria-label="级联选择" @keydown="keyboard"><input v-if="filterable" v-model="query" class="hys-ui-v4-control" placeholder="搜索分类" aria-label="搜索分类"/><div v-if="query" class="hys-ui-v4-scroll hys-ui-cascader-results"><button v-for="match in matches" :key="match.path.join('/')" type="button" class="hys-ui-v4-option" @click="update(match.path);close(true)">{{match.label}}</button><p v-if="!matches.length">无匹配分类</p></div><div v-else class="hys-ui-v4-columns"><div v-for="(nodes,depth) in levels" :key="depth" class="hys-ui-v4-scroll hys-ui-v4-level" role="group" :aria-label="'第'+(depth+1)+'级'"><button v-for="node in nodes" :key="node.value" type="button" class="hys-ui-v4-option" :disabled="node.disabled" :aria-current="path[depth]===node.value?'true':undefined" @click="select(node,depth)"><slot name="option" :node="node">{{node.label}}</slot><ChevronRight v-if="node.children?.length" :size="15"/><Check v-else-if="path[depth]===node.value" :size="15"/></button></div></div><button v-if="clearable&&modelValue.length" type="button" class="hys-ui-v4-option" @click="update([]);emit('clear');close(true)">清空选择</button><button type="button" class="hys-ui-v4-option" @click="close(true)">关闭</button></div></Teleport></div></template>
